# A year is a leap year if it divides by 4, but not by 100 unless it divides by 400.
function divisible_by(year, n) {
    return year % n == 0
}

{
    if (divisible_by($1, 4) && (!divisible_by($1, 100) || divisible_by($1, 400)))
        print "true"
    else
        print "false"
}

